1	<#
2	.SYNOPSIS
3	    将所有 Claude Code 项目的 memory 和对话历史同步到本仓库。
4	.DESCRIPTION
5	    扫描 ~/.claude/projects/ 下所有项目，将 memory 和 session JSONL
6	    以项目名为子目录复制到本仓库，保持项目隔离。
7	    仅拷贝新增或有变化的文件（比较时间戳和大小），跳过未修改文件。
8	#>
9	
10	$claudeProjects = Join-Path $env:USERPROFILE ".claude\projects"
11	$memoryRoot = Join-Path $PSScriptRoot "memory"
12	$sessionsRoot = Join-Path $PSScriptRoot "sessions"
13	
14	if (-not (Test-Path $memoryRoot)) {
15	    New-Item -ItemType Directory -Force $memoryRoot | Out-Null
16	}
17	if (-not (Test-Path $sessionsRoot)) {
18	    New-Item -ItemType Directory -Force $sessionsRoot | Out-Null
19	}
20	
21	function Copy-IfChanged {
22	    param([string]$SrcFile, [string]$DstDir)
23	    $dstFile = Join-Path $DstDir (Split-Path $SrcFile -Leaf)
24	    if (Test-Path $dstFile) {
25	        $src = Get-Item $SrcFile
26	        $dst = Get-Item $dstFile
27	        if ($src.LastWriteTime -eq $dst.LastWriteTime -and $src.Length -eq $dst.Length) {
28	            return $false
29	        }
30	    }
31	    Copy-Item $SrcFile $DstDir -Force
32	    return $true
33	}
34	
35	Get-ChildItem $claudeProjects -Directory | ForEach-Object {
36	    $projName = $_.Name
37	
38	    $memSrc = Join-Path $_.FullName "memory"
39	    if (Test-Path $memSrc) {
40	        $files = Get-ChildItem $memSrc -File
41	        if ($files.Count -gt 0) {
42	            $projDir = Join-Path $memoryRoot $projName
43	            if (-not (Test-Path $projDir)) {
44	                New-Item -ItemType Directory -Force $projDir | Out-Null
45	            }
46	            $copied = 0
47	            foreach ($f in $files) {
48	                if (Copy-IfChanged $f.FullName $projDir) { $copied++ }
49	            }
50	            if ($copied -gt 0) {
51	                Write-Output "Memory: $projName ($copied/$($files.Count) updated)"
52	            }
53	        }
54	    }
55	
56	    $jsonls = Get-ChildItem $_.FullName -Filter "*.jsonl" -File
57	    if ($jsonls.Count -gt 0) {
58	        $projDir = Join-Path $sessionsRoot $projName
59	        if (-not (Test-Path $projDir)) {
60	            New-Item -ItemType Directory -Force $projDir | Out-Null
61	        }
62	        $copied = 0
63	        foreach ($f in $jsonls) {
64	            if (Copy-IfChanged $f.FullName $projDir) { $copied++ }
65	        }
66	        if ($copied -gt 0) {
67	            Write-Output "Sessions: $projName ($copied/$($jsonls.Count) updated)"
68	        }
69	    }
70	}
71	
72	Write-Output "Done."
