# --- Profile inbox check ---
$inbox = Join-Path $PSScriptRoot "profile-inbox.md"
if (Test-Path $inbox) {
    $lines = (Get-Content $inbox | Where-Object { $_.Trim() -ne "" }).Count
    if ($lines -gt 0) {
        Write-Output "PROFILE_INBOX: profile-inbox.md has pending updates, please process."
    }
}

Write-Output "Done."

